func newToolTrust() unsafe.Pointer { return unsafe.Pointer(new(agent.ToolTrust)) }

func newNToolTrust(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]agent.ToolTrust, n)))
}

func ptrToolTrust(p unsafe.Pointer, c int32) any {
	r := (*agent.ToolTrust)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.AgentDefinitionID))
	case 4:
		return &r.ToolName
	case 5:
		return (*int64)(unsafe.Pointer(&r.Streak))
	case 6:
		return (*int64)(unsafe.Pointer(&r.Approvals))
	case 7:
		return (*int64)(unsafe.Pointer(&r.Modifications))
	case 8:
		return (*int64)(unsafe.Pointer(&r.Rejections))
	case 9:
		return (*int64)(unsafe.Pointer(&r.ExecutionFailures))
	case 10:
		return (*string)(unsafe.Pointer(&r.EarnedTier))
	case 11:
		return &r.LastDecisionAt
	case 12:
		return &r.PromotedAt
	case 13:
		return &r.DemotedAt
	case 14:
		return &r.Version
	case 15:
		return &r.CreatedAt
	case 16:
		return &r.UpdatedAt
	}
	return nil
}

func valueToolTrust(p unsafe.Pointer, c int32) any {
	r := (*agent.ToolTrust)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.AgentDefinitionID)
	case 4:
		return r.ToolName
	case 5:
		return int64(r.Streak)
	case 6:
		return int64(r.Approvals)
	case 7:
		return int64(r.Modifications)
	case 8:
		return int64(r.Rejections)
	case 9:
		return int64(r.ExecutionFailures)
	case 10:
		if r.EarnedTier == "" {
			return nil
		}
		return string(r.EarnedTier)
	case 11:
		if r.LastDecisionAt == nil {
			return nil
		}
		return *r.LastDecisionAt
	case 12:
		if r.PromotedAt == nil {
			return nil
		}
		return *r.PromotedAt
	case 13:
		if r.DemotedAt == nil {
			return nil
		}
		return *r.DemotedAt
	case 14:
		return r.Version
	case 15:
		return r.CreatedAt
	case 16:
		return r.UpdatedAt
	}
	return nil
}

func beforeCreateToolTrust(ctx context.Context, p unsafe.Pointer) error {
	return (*agent.ToolTrust)(p).BeforeCreate(ctx)
}

